import json
categories={'Pneumatics':['Compact cylinder','Solenoid valve','Air preparation unit','Push-in fitting','Pneumatic tubing','Pressure regulator','Air blow gun','Silencer','Pressure switch'],'Fasteners':['Hex bolt M12','Socket screw M8','Flange nut','Flat washer','Threaded rod','Anchor bolt','Lock washer','Rivet assortment','Retaining ring'],'Power transmission':['Deep groove bearing','V-belt','Flexible coupling','Roller chain','Sprocket','Linear guide','Timing pulley','Shaft collar','Bearing housing'],'Electrical':['Proximity sensor','Contactor','Circuit breaker','Terminal block','Industrial connector','Cable gland','DIN rail supply','Emergency stop','Signal beacon'],'Tools':['Torque wrench','Digital caliper','Socket set','Combination wrench','Drill bit set','Insulated pliers','Deburring tool','Bench vice','Measuring tape'],'Safety':['Safety glasses','Work gloves','Ear defenders','Safety helmet','Respirator','High-vis vest','Safety shoes','Face shield','First aid kit']}
products=[]
for ci,(cat,names) in enumerate(categories.items()):
 for i,name in enumerate(names):
  n=ci*9+i
  products.append(dict(id=f'p{n+1}',sku=f'{["PNE","FAS","DRV","ELE","TLS","SAF"][ci]}-{3201+i}',name=name,brand=['Festo','Würth','SKF','Siemens','Knipex','Uvex'][ci],category=cat,price=round(18.5+n*7.35+(i%3)*42,2),stock=0 if n%11==8 else 18+n*3,unit='piece',leadDays=7 if n%11==8 else 2,description=f'Industrial-grade {name.lower()} for reliable daily operation. Precision engineered for demanding workshop and production environments. Technical specifications are illustrative demo data.',featured=i<2,active=True))
companies=[dict(id=f'c{i+1}',name=n,code=f'DE-{1001+i}',tier=['Gold','Silver','Platinum'][i%3],discount=[18,12,22,15,10,20][i],approvalThreshold=1000+i*500,creditLimit=25000,city=city,country=country,active=True) for i,(n,city,country) in enumerate([('Müller Maschinenbau GmbH','Stuttgart','DE'),('Alpen Technik AG','Zürich','CH'),('Weber Industriebedarf','München','DE'),('Kraft Anlagenbau GmbH','Wien','AT'),('Nordwerk Engineering','Hamburg','DE'),('Bergmann Automation','Graz','AT')])]
users=[dict(id=f'u{i+1}',name=n,email=f'{email}@demo.tradehub',password=pw,role=role,companyId='c1',active=True) for i,(n,email,pw,role) in enumerate([('Anna Müller','buyer','Demo@123','buyer'),('Markus Weber','manager','Demo@123','customer_admin'),('Sophie Wagner','admin','Admin@123','admin'),('Thomas Fischer','sales','Sales@123','field_sales'),('Laura Schmidt','support','Support@123','inside_sales')])]
orders=[]
for i,status in enumerate(['shipped','processing','delivered','pending_approval','submitted','delivered']):
 p=products[i]; price=round(p['price']*.82,2); qty=80 if status=='pending_approval' else i+3
 orders.append(dict(id=f'o{i+1}',number=f'TH-2026-{1042+i}',companyId='c1' if i<4 else 'c2',userId='u1',items=[dict(productId=p['id'],sku=p['sku'],name=p['name'],qty=qty,unitPrice=price)],status=status,total=round(price*qty,2),reference=f'PO-2026-{201+i}',notes='',createdAt=f'2026-10-{22+i}T10:00:00Z',erpStatus='pending' if status in ['submitted','pending_approval'] else 'synced',tracking='Demo tracking · DACH logistics' if status in ['shipped','delivered'] else '',invoiceId=f'inv{i}' if status=='delivered' else None))
invoices=[dict(id=o['invoiceId'],number=f'DEMO-INV-{1042+i}',orderId=o['id'],companyId=o['companyId'],amount=o['total'],date=o['createdAt'],status='sample') for i,o in enumerate(orders) if o['invoiceId']]
seed=dict(version=1,companies=companies,users=users,products=products,carts={c['id']:[] for c in companies},favorites={'c1':['p1','p10','p19']},orders=orders,invoices=invoices,templates=[dict(id='t1',companyId='c1',name='Workshop essentials',items=[dict(productId='p1',qty=5),dict(productId='p10',qty=20)])],drafts=[],support=[],settings=dict(portalName='TradeHub',approvalThreshold=1000),odoo=dict(url='https://odoo-demo.example.invalid',database='tradehub_demo',version='17.0',user='portal_demo',interval=60,modules=['Products','Customers','Stock','Orders','Invoices'],lastSync=None,mapping=[dict(entity=a,model=b,fields='Exact fields / custom modules TBC') for a,b in [('Products','product.product / product.template'),('Customers','res.partner'),('Prices','product.pricelist'),('Stock','stock.quant'),('Orders','sale.order'),('Invoices','account.move')]]),syncLogs=[])
for path in ['src/data/seed.json','public/seed.json']:
 with open(path,'w') as f: json.dump(seed,f,ensure_ascii=False,indent=2)
# Enrich the original representative dataset with managed categories and version-2 fields.
import subprocess
subprocess.run(['node', 'scripts/migrate-seed.mjs'], check=True)
